  ('conecta-x', 1, 'Conecta tu cuenta de X', 'Vinculá tu cuenta de X con tu perfil de Sura y sumá los puntos apenas se confirme el enlace.', 120, '/assets/missions/covers/conecta-x.webp', 'sociales', false, true, false, null),
